def flatten() -> tuple[list[str], list[str]]:
    """Return (texts, labels) as parallel lists."""
    texts: list[str] = []
    labels: list[str] = []
    for skill, utterances in TRAINING_DATA.items():
        for u in utterances:
            texts.append(u)
            labels.append(skill)
    return texts, labels


def stats() -> str:
    lines = ["Intent dataset:"]
    total = 0
    for skill, utts in sorted(TRAINING_DATA.items(), key=lambda kv: -len(kv[1])):
        lines.append(f"  {skill:20} {len(utts):3}")
        total += len(utts)
    lines.append(f"  {'TOTAL':20} {total:3} across {len(TRAINING_DATA)} classes")
    return "\n".join(lines)


if __name__ == "__main__":
    print(stats())
